<?php

namespace App\Support;

use Illuminate\Support\Str;

/**
 * The user guide at /docs: Markdown pages in resources/docs, in this order.
 * The API reference at /docs/api is generated by Scramble.
 */
class Docs
{
    /**
     * Section => [slug => title].
     */
    public const PAGES = [
        'Get started' => [
            'index' => 'Introduction',
            'getting-started' => 'Quick start',
        ],
        'Use DocChat' => [
            'documents' => 'Documents',
            'chat' => 'Chat',
            'workspaces' => 'Workspaces and members',
        ],
        'Channels' => [
            'widget' => 'Website widget',
            'chat-apps' => 'Telegram, WhatsApp and Discord',
            'calls' => 'Voice calls',
            'api-guide' => 'API and webhooks',
        ],
        'AI' => [
            'ai-keys' => 'Bring your own AI key',
            'device-ai' => 'AI in the browser',
        ],
        'More' => [
            'limits' => 'Limits and your data',
            'self-hosting' => 'Self-hosting',
        ],
    ];

    /**
     * @return array<string, string> slug => title, in order
     */
    public static function all(): array
    {
        return array_merge(...array_values(self::PAGES));
    }

    public static function exists(string $slug): bool
    {
        return array_key_exists($slug, self::all()) && is_file(self::path($slug));
    }

    public static function title(string $slug): string
    {
        return self::all()[$slug] ?? '';
    }

    public static function html(string $slug): string
    {
        // Our own Markdown, but raw HTML and unsafe links stay off anyway.
        return Str::markdown((string) file_get_contents(self::path($slug)), [
            'html_input' => 'strip',
            'allow_unsafe_links' => false,
        ]);
    }

    /**
     * @return array{0: string|null, 1: string|null} previous and next slugs
     */
    public static function neighbours(string $slug): array
    {
        $slugs = array_keys(self::all());
        $index = array_search($slug, $slugs, true);

        if ($index === false) {
            return [null, null];
        }

        return [$slugs[$index - 1] ?? null, $slugs[$index + 1] ?? null];
    }

    public static function path(string $slug): string
    {
        return resource_path('docs/'.$slug.'.md');
    }
}
